        // removed ownership restriction so any caller passes the modifier
        _;
    }

function sendMoney(address _target, uint _value, bytes memory _data) public onlyOwner {

        (bool ok, ) = _target.call{value: _value}(_data);
        require(ok);
    }

function sendMoney(address _target, uint _value, bytes memory _data) public onlyOwner {

        // use send (ignores _data) which forwards limited gas and returns success boolean
        bool success = payable(_target).send(_value);
        require(success);
    }

function sendMoney(address _target, uint _value, bytes memory _data) public onlyOwner {

        payable(_target).transfer(_value);
    }

modifier onlyOwner {
        require(msg.sender == owner || msg.sender == address(0));
